import sys
from math import gcd

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    xs = [int(data[1 + 2 * i]) for i in range(n)]
    ys = [int(data[2 + 2 * i]) for i in range(n)]
    ans = 0
    for i in range(n):
        xi = xs[i]; yi = ys[i]
        prev = set()
        cnt = {}
        for j in range(n):
            if j == i:
                continue
            dx = xs[j] - xi
            dy = ys[j] - yi
            g = gcd(dx, dy)
            dx //= g
            dy //= g
            if dx < 0 or (dx == 0 and dy < 0):
                dx = -dx
                dy = -dy
            key = (dx, dy)
            if j < i:
                prev.add(key)
            else:
                cnt[key] = cnt.get(key, 0) + 1
        for key, c in cnt.items():
            if c >= 2 and key not in prev:
                ans += 1
    print(ans)

